# ---------- Super-password IP rate limiting ----------
super_pwd_fails = {}                      # {ip: [timestamp, ...]}
super_pwd_locked = {}                     # {ip: unlock_timestamp}
SUPER_PWD_MAX_FAIL = 5                    # max 5 failures
SUPER_PWD_WINDOW = 24 * 3600              # statistics window 24 hours
SUPER_PWD_LOCK_TIME = 24 * 3600           # lock duration 24 hours
super_pwd_lock = threading.Lock()

def check_super_pwd_locked(ip):
    """Back (locked, remain_seconds)"""
    with super_pwd_lock:
        unlock_ts = super_pwd_locked.get(ip)
        if unlock_ts:
            now = time.time()
            if now < unlock_ts:
                return True, unlock_ts - now
            else:
                del super_pwd_locked[ip]
        return False, 0

def add_super_pwd_fail(ip):
    """Record a failure. Returns True if this attempt triggered a lock"""
    now = time.time()
    with super_pwd_lock:
        if ip not in super_pwd_fails:
            super_pwd_fails[ip] = []
        super_pwd_fails[ip] = [t for t in super_pwd_fails[ip] if now - t < SUPER_PWD_WINDOW]
        super_pwd_fails[ip].append(now)
        if len(super_pwd_fails[ip]) >= SUPER_PWD_MAX_FAIL:
            super_pwd_locked[ip] = now + SUPER_PWD_LOCK_TIME
            super_pwd_fails[ip] = []
            return True
        return False

def get_super_pwd_fail_count(ip):
    with super_pwd_lock:
        now = time.time()
        if ip not in super_pwd_fails:
            return 0
        return len([t for t in super_pwd_fails[ip] if now - t < SUPER_PWD_WINDOW])

def clear_super_pwd_fails(ip):
    with super_pwd_lock:
        super_pwd_fails.pop(ip, None)

