# ---------- Super-password hash storage ----------
def load_super_password():
    if os.path.exists(SUPER_PASSWORD_FILE):
        with open(SUPER_PASSWORD_FILE, 'r') as f:
            data = json.load(f)
            return data.get('password_hash', '')
    else:
        default_hash = generate_password_hash("superadmin123")
        save_super_password(default_hash)
        return default_hash

def save_super_password(password_hash):
    with open(SUPER_PASSWORD_FILE, 'w') as f:
        json.dump({"password_hash": password_hash}, f)

def verify_super_password(password):
    stored_hash = load_super_password()
    return check_password_hash(stored_hash, password)

def change_super_password(old_password, new_password):
    if not verify_super_password(old_password):
        return False, "Original password is incorrect"
    if len(new_password.strip()) == 0:
        return False, "New password cannot be empty"
    new_hash = generate_password_hash(new_password)
    save_super_password(new_hash)
    return True, "Super password updated successfully"

# ---------- User data ----------
def load_users():
    if os.path.exists(USERS_FILE):
        with open(USERS_FILE, 'r') as f: return json.load(f)
    users = {}
    for name, info in DEFAULT_USERS.items():
        users[name] = {"password_hash": generate_password_hash(info["password"]), "avatar": info["avatar"], "role": info["role"]}
    save_users(users)
    try:
        from PIL import Image
        for fname, color in [("default_admin.png", (88,166,255,255)), ("default_user.png", (139,148,158,255))]:
            path = os.path.join(AVATAR_DIR, fname)
            if not os.path.exists(path):
                Image.new('RGBA', (64,64), color).save(path)
    except: pass
    return users

def save_users(users):
    with open(USERS_FILE, 'w') as f: json.dump(users, f, indent=2)

users_db = load_users()

# ---------- Audit log ----------
def audit_log(username, action, details, success=True):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        ip = request.remote_addr
    except:
        ip = "unknown"
    log_line = f"{timestamp} | {username} | {ip} | {action} | {details} | {'Success' if success else 'Failed'}\n"
    today = datetime.now().strftime("%Y-%m-%d")
    log_path = os.path.join(LOG_DIR, f"audit_{today}.log")
    try:
        with open(log_path, 'a', encoding='utf-8') as f:
            f.write(log_line)
    except: pass

