# ---------- Permission decorators ----------
def login_required(f):
    @wraps(f)
    def dec(*a,**k):
        if 'username' not in session: return jsonify({"error":"Not logged in"}), 401
        last_activity = session.get('last_activity')
        if last_activity and (datetime.now() - datetime.fromtimestamp(last_activity)).total_seconds() > 900:
            session.clear()
            return jsonify({"error": "Session expired"}), 401
        session['last_activity'] = datetime.now().timestamp()
        return f(*a,**k)
    return dec

def admin_required(f):
    @wraps(f)
    def dec(*a,**k):
        if 'username' not in session: return jsonify({"error":"Not logged in"}), 401
        username = session['username']
        if username not in users_db or users_db[username].get('role') != 'admin':
            return jsonify({"error":"Admin permission required"}), 403
        return f(*a,**k)
    return dec

# ==================== Recovery Mode Core Logic ====================
def recovery_authorized():
    """Check if the current session passed recovery-mode verification and the heartbeat has not expired"""
    if not session.get('recovery_authorized'):
        return False
    rid = session.get('recovery_sid')
    if not rid:
        return False
    with recovery_lock:
        last = recovery_sessions.get(rid)
        if last is None:
            return False
        if time.time() - last > RECOVERY_HEARTBEAT_TIMEOUT:
            return False
    return True

