def recovery_cleaner_loop():
    """Background cleanup thread: scan timed-out recovery sessions"""
    while True:
        try:
            time.sleep(5)
            now = time.time()
            with recovery_lock:
                expired = [k for k, v in recovery_sessions.items() if now - v > RECOVERY_HEARTBEAT_TIMEOUT]
                for k in expired:
                    recovery_sessions.pop(k, None)
        except Exception as e:
            print(f"[recovery-cleaner] error: {e}")

def recovery_monitor_loop():
    """Background monitor push: every 3s, validate connections one by one"""
    while True:
        try:
            time.sleep(3)
            valid_data = get_recovery_monitor_data()
            error_data = {'time': 'Error', 'cpu_temp': 'Error', 'battery': 'Error',
                          'load': 'Error', 'uptime': 'Error', 'kernel': 'Error'}
            now = time.time()
            # Collect all active sids
            sids = list(recovery_clients.keys())
            for sid in sids:
                rid = recovery_clients.get(sid)
                authed = False
                if rid:
                    with recovery_lock:
                        last = recovery_sessions.get(rid)
                        if last and now - last <= RECOVERY_HEARTBEAT_TIMEOUT:
                            authed = True
                socketio.emit('monitor', valid_data if authed else error_data,
                              namespace='/recovery', to=sid)
        except Exception as e:
            print(f"[recovery-monitor] error: {e}")

def get_recovery_monitor_data():
    """Get top monitor bar data"""
    data = {'time': '-', 'cpu_temp': '-', 'battery': '-', 'load': '-', 'uptime': '-', 'kernel': '-'}
    # Time
    try:
        r = subprocess.run(['date', '+%Y-%m-%d %H:%M:%S'], capture_output=True, text=True, timeout=2)
        if r.returncode == 0 and r.stdout.strip():
            data['time'] = r.stdout.strip()
    except: pass
    # CPU temperature (sensors, 8-core average)
    try:
        r = subprocess.run(['sensors'], capture_output=True, text=True, timeout=3)
        if r.returncode == 0:
            temps = re.findall(r'Core\s+\d+:\s+\+([\d.]+)\s*°C', r.stdout)
            if temps:
                avg = sum(float(t) for t in temps) / len(temps)
                data['cpu_temp'] = f"{avg:.1f}°C"
    except: pass
    # Battery (upower)
    try:
        r = subprocess.run(['upower', '-e'], capture_output=True, text=True, timeout=2)
        if r.returncode == 0:
            bat_lines = [l.strip() for l in r.stdout.split('\n') if 'BAT' in l and l.strip()]
            if bat_lines:
                r2 = subprocess.run(['upower', '-i', bat_lines[0]], capture_output=True, text=True, timeout=2)
                if r2.returncode == 0:
                    m = re.search(r'percentage:\s+(\d+)%', r2.stdout)
                    if m:
                        data['battery'] = m.group(1) + '%'
    except: pass
    # Load + boot time (uptime command)
    try:
        r = subprocess.run(['uptime'], capture_output=True, text=True, timeout=2)
        if r.returncode == 0 and r.stdout.strip():
            out = r.stdout.strip()
            m = re.search(r'load average:\s+([\d.]+),\s+([\d.]+),\s+([\d.]+)', out)
            if m:
                data['load'] = f"{m.group(1)} / {m.group(2)} / {m.group(3)}"
            m2 = re.search(r'up\s+(.+?),\s+\d+\s+user', out)
            if m2:
                data['uptime'] = 'up ' + m2.group(1).strip()
    except: pass
    # Kernel version
    try:
        r = subprocess.run(['uname', '-r'], capture_output=True, text=True, timeout=2)
        if r.returncode == 0 and r.stdout.strip():
            data['kernel'] = r.stdout.strip()
    except: pass
    return data

# Start background threads
threading.Thread(target=recovery_cleaner_loop, daemon=True).start()
threading.Thread(target=recovery_monitor_loop, daemon=True).start()

# ==================== Minecraft Control ====================
COMMON_ARCHIVE_EXT = ('.zip', '.gz', '.tar', '.tar.gz', '.tgz', '.7z', '.rar', '.bz2', '.xz', '.zst')

def find_server_jar():
    """Find the server core jar in the MC directory (any file name)."""
    for name in ("server.jar", "paper.jar", "spigot.jar", "purpur.jar", "bukkit.jar"):
        p = os.path.join(MC_DIR, name)
        if os.path.exists(p):
            return p
    jars = sorted(glob.glob(os.path.join(MC_DIR, "*.jar")))
    return jars[0] if jars else None

def detect_mc_launcher():
    """Return the MC launch method from env vars injected by the install script (preinstall.sh); no probing commands are run.

    MC_LAUNCH_TYPE is systemd / screen / tmux, auto-detected by preinstall.sh at install time,
    and written into the systemd unit after user confirmation. The panel no longer runs systemctl/screen/tmux scans."""
    return (MC_LAUNCH_TYPE or None), SERVICE_NAME

def run_mc_control(cmd):
    """Execute control commands per the MC launch method; compatible with systemd / screen / tmux."""
    launcher, name = detect_mc_launcher()
    if launcher == 'systemd':
        proc = subprocess.run("sudo /usr/bin/systemctl %s %s" % (cmd, shlex.quote(name)),
                              shell=True, capture_output=True, text=True)
        return proc.returncode==0, proc.stdout.strip(), proc.stderr.strip()
    if launcher == 'screen':
        if cmd == 'is-active':
            try:
                r = subprocess.run(['screen', '-ls'], capture_output=True, text=True, timeout=5)
                ok = name in r.stdout
                return ok, ('active' if ok else 'inactive'), ''
            except Exception as e:
                return False, '', str(e)
        if cmd == 'start':
            if MC_LAUNCH_CMD:
                launch = MC_LAUNCH_CMD
            else:
                script = os.path.join(MC_DIR, 'start.sh')
                jar = find_server_jar()
                if not (os.path.exists(script) or jar):
                    return False, '', 'No start.sh or usable jar found in MC directory'
                launch = "bash start.sh" if os.path.exists(script) else ("java -jar " + shlex.quote(os.path.basename(jar)) + " nogui")
            proc = subprocess.run("cd %s && screen -dmS %s %s" % (shlex.quote(MC_DIR), shlex.quote(name), launch),
                                  shell=True, capture_output=True, text=True)
            return proc.returncode==0, 'Screen start command sent', proc.stderr.strip()
        if cmd == 'stop':
            stuff_cmd = "screen -S " + shlex.quote(name) + " -X stuff " + chr(34) + "stop" + chr(92) + "n" + chr(34)
            proc = subprocess.run(stuff_cmd, shell=True, capture_output=True, text=True)
            return proc.returncode==0, 'Stop command sent to screen', proc.stderr.strip()
    if launcher == 'tmux':
        if cmd == 'is-active':
            try:
                r = subprocess.run(['tmux', 'ls'], capture_output=True, text=True, timeout=5)
                ok = name in r.stdout
                return ok, ('active' if ok else 'inactive'), ''
            except Exception as e:
                return False, '', str(e)
        if cmd == 'start':
            if MC_LAUNCH_CMD:
                launch = MC_LAUNCH_CMD
            else:
                script = os.path.join(MC_DIR, 'start.sh')
                jar = find_server_jar()
                if not (os.path.exists(script) or jar):
                    return False, '', 'No start.sh or usable jar found in MC directory'
                launch = "bash start.sh" if os.path.exists(script) else ("java -jar " + shlex.quote(os.path.basename(jar)) + " nogui")
            proc = subprocess.run("cd %s && tmux new-session -d -s %s '%s'" % (shlex.quote(MC_DIR), shlex.quote(name), launch),
                                  shell=True, capture_output=True, text=True)
            return proc.returncode==0, 'Tmux start command sent', proc.stderr.strip()
        if cmd == 'stop':
            proc = subprocess.run("tmux send-keys -t %s stop Enter" % shlex.quote(name),
                                  shell=True, capture_output=True, text=True)
            return proc.returncode==0, 'Stop command sent to tmux', proc.stderr.strip()
    return False, '', 'MC launch method not detected (systemd/screen/tmux), service name: ' + name

def get_server_status():
    ok, out, _ = run_mc_control("is-active")
    return "running" if ok and out=="active" else "stopped"

def start_server():
    if get_server_status()=="running": return False, "Server is already running"
    ok, _, err = run_mc_control("start")
    return (True, "Start command sent") if ok else (False, f"Start failed: {err}")

def stop_server():
    if get_server_status()=="stopped": return False, "Server not running"
    ok, _, err = run_mc_control("stop")
    return (True, "Stop command sent") if ok else (False, f"Stop failed: {err}")

def restart_server():
    """Quick restart: systemd runs systemctl restart directly (not stop+start).
    screen/tmux have no restart command; compose stop → wait for save → start."""
    launcher, _ = detect_mc_launcher()
    if launcher == 'systemd':
        name = SERVICE_NAME
        proc = subprocess.run("sudo /usr/bin/systemctl restart %s" % shlex.quote(name),
                              shell=True, capture_output=True, text=True)
        if proc.returncode == 0:
            return True, "Quick restart complete (systemctl restart %s)" % name
        return False, "Quick restart failed: %s" % (proc.stderr.strip() or 'Unknown error')
    if get_server_status() == "stopped":
        return start_server()
    ok, _, err = run_mc_control("stop")
    if not ok:
        return False, "Quick restart failed (stop stage): %s" % err
    time.sleep(5)
    return start_server()

def extract_version(fname):
    m = re.search(r'(\d+\.\d+(?:\.\d+)?)', fname)
    return m.group(1) if m else "Unknown"

def sizeof_fmt(num):
    for unit in ['B','K','M','G']:
        if abs(num)<1024.0: return f"{num:3.1f}{unit}"
        num/=1024.0
    return f"{num:.1f}G"

def strip_ansi(text):
    return re.compile(r'\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])').sub('', text)

def get_system_info():
    try:
        with open('/proc/meminfo') as f:
            for line in f:
                if line.startswith('MemTotal:'): mem_total = int(line.split()[1])//1024
                elif line.startswith('MemAvailable:'): mem_avail = int(line.split()[1])//1024
        mem_used = mem_total - mem_avail
        mem_percent = (mem_used/mem_total)*100 if mem_total>0 else 0
        mem = {"total":mem_total,"used":mem_used,"available":mem_avail,"percent":round(mem_percent,1)}
    except: mem = {"total":0,"used":0,"available":0,"percent":0}
    try:
        with open('/proc/loadavg') as f:
            ld = f.read().split()
            load_1min,load_5min,load_15min = float(ld[0]),float(ld[1]),float(ld[2])
        cpu_count = os.cpu_count() or 1
        load_percent = round((load_1min/cpu_count)*100,1)
    except: load_1min=load_5min=load_15min=0.0; load_percent=0; cpu_count=1
    try:
        stat = os.statvfs(MC_DIR)
        total = (stat.f_blocks*stat.f_frsize)//(1024**3)
        free = (stat.f_bfree*stat.f_frsize)//(1024**3)
        used = total-free
        percent = (used/total)*100 if total>0 else 0
        disk = {"total":total,"used":used,"free":free,"percent":round(percent,1)}
    except: disk = {"total":0,"used":0,"free":0,"percent":0}
    return {"memory":mem,"cpu_load":{"1min":load_1min,"5min":load_5min,"15min":load_15min,"percent":load_percent,"cores":cpu_count},"disk":disk}

class RCONClient:
    """Pure-socket Minecraft RCON client (same origin as the Cyber dashboard).

    No mcrcon binary: it uses signal.alarm for timeouts, which throws in worker threads
    "signal only works in main thread". Protocol: TCP + 4-byte length + (id, type, payload).
    """

    def __init__(self, host, password, port=25575, timeout=3):
        self.host = host
        self.password = password
        self.port = port
        self.timeout = timeout
        self.sock = None

    def connect(self):
        self.sock = socket.create_connection((self.host, self.port),
                                             timeout=self.timeout)
        self.sock.settimeout(self.timeout)
        self._send(3, self.password)          # SERVERDATA_AUTH
        _id, _type, _data = self._read()
        if _id == -1:
            raise RuntimeError("RCON authentication failed (wrong password)")
        return self

    def command(self, cmd):
        self._send(2, cmd)                    # SERVERDATA_EXECCOMMAND
        _id, _type, data = self._read()
        return data

    def close(self):
        if self.sock:
            try:
                self.sock.close()
            except Exception:
                pass
            self.sock = None

    def _send(self, ptype, payload):
        if isinstance(payload, str):
            payload = payload.encode("utf-8")
        body = struct.pack("<ii", 1, ptype) + payload + b"\x00\x00"
        self.sock.sendall(struct.pack("<i", len(body)) + body)

    def _read(self):
        ln = struct.unpack("<i", self._recv_exact(4))[0]
        body = self._recv_exact(ln)
        _id, ptype = struct.unpack("<ii", body[:8])
        data = body[8:ln - 2].decode("utf-8", errors="replace")
        return _id, ptype, data

    def _recv_exact(self, n):
        buf = b""
        while len(buf) < n:
            chunk = self.sock.recv(n - len(buf))
            if not chunk:
                raise ConnectionError("RCON connection closed by server")
            buf += chunk
        return buf

    def __enter__(self):
        return self.connect()

    def __exit__(self, *exc):
        self.close()
        return False


def rcon_exec(cmd):
    """Pure-socket RCON command executor (same as the Cyber dashboard); returns cleaned output or None on failure"""
    try:
        with RCONClient(RCON_HOST, RCON_PASS, port=RCON_PORT, timeout=3) as rcon:
            out = rcon.command(cmd)
        out = strip_ansi(out)
        out = re.sub(r"§[0-9a-fk-or]", "", out)
        return out.strip()
    except Exception:
        return None


def parse_list_response(resp):
    """Same origin as the Cyber dashboard: loosely parse /list output (EN/CN/color codes/plugin rewrites); returns (online, max)"""
    if not resp:
        return None, None
    clean = re.sub(r"§[0-9a-fk-or]", "", resp)
    players = []
    sep = ": " if ": " in clean else ("：" if "：" in clean else None)
    if sep is not None:
        rest = clean.split(sep, 1)[1].strip()
        if rest:
            players = [p.strip() for p in rest.split(",") if p.strip()]
    online = maxp = None
    m = re.search(r"(\d+)\s+of\s+a\s+max\s+of\s+(\d+)", clean)          # vanilla English list
    if not m:
        m = re.search(r"(\d+)\s*/\s*(\d+)", clean)                         # Essentials-style X/Y
    if not m:
        m = re.search(r"在线\s*(\d+)[^0-9]{0,8}(\d+)", clean)               # Cyber dashboard CN branch
    if not m:
        m = re.search(r"有\s*(\d+)\s*位玩家在线[^0-9]*(\d+)", clean)       # vanilla CN list
    if not m:
        m = re.search(r"(\d+)[^\d]*(\d+)", clean)                          # fallback: first two numbers
    if m:
        online, maxp = int(m.group(1)), int(m.group(2))
    if online is None and players:
        online = len(players)
    return online, maxp


def get_mc_server_uptime_secs():
    """Same as the Cyber dashboard: read real uptime (seconds) of the Java server process.

    Method 1 (most accurate): starttime from /proc/<pid>/stat + system boot time (/proc/stat btime),
    pure system-level, no plugin/command dependency. Method 2 (fallback): the "Done (" timestamp in the log.
    Returns None on failure.
    """
    try:
        out = subprocess.check_output(["pgrep", "-f", r"server\.jar"], timeout=3).decode().strip()
        pid = out.split("\n")[0]
        with open("/proc/%s/stat" % pid, "r") as f:
            parts = f.read().split()
        start_ticks = float(parts[21])
        boot = 0.0
        with open("/proc/stat") as f:
            for line in f:
                if line.startswith("btime "):
                    boot = float(line.split()[1])
                    break
        ticks = float(os.sysconf("SC_CLK_TCK"))
        start_ts = boot + start_ticks / ticks
        if start_ts > 0:
            return max(0, time.time() - start_ts)
    except Exception:
        pass
    try:
        with open(LOG_FILE, 'r', encoding='utf-8', errors='ignore') as f:
            head = f.read(200000)
        m = re.findall(r"\[(\d{1,2}:\d{2}:\d{2})\].*?Done \(", head)
        if m:
            hh, mm, ss = map(int, m[-1].split(":"))
            now = datetime.now()
            start = now.replace(hour=hh, minute=mm, second=ss, microsecond=0)
            days = 0
            while start > now and days < 30:
                start -= timedelta(days=1)
                days += 1
            return max(0, (now - start).total_seconds())
    except Exception:
        pass
    return None


def fmt_uptime(seconds):
    """Same as the Cyber dashboard: seconds → human-readable duration"""
    if seconds is None:
        return "Unknown"
    d, rem = divmod(int(seconds), 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    if d:
        return "%dd %dh %dm %ds" % (d, h, m, s)
    if h:
        return "%dh %dm %ds" % (h, m, s)
    if m:
        return "%dm %ds" % (m, s)
    return "%d s" % s


def get_mc_server_info():
    running = get_server_status()=="running"
    info = {"online":0,"max":0,"tps":0.0,"uptime":"Unknown","memory_used_mb":0,"memory_max_mb":0,"server_running":running}
    if not running: info["uptime"]="Server not running"; return info
    # Same as the Cyber dashboard: batch native commands over one connection (list prefers minecraft:list, falls back to list)
    list_out = tps_out = gc_out = None
    try:
        with RCONClient(RCON_HOST, RCON_PASS, port=RCON_PORT, timeout=3) as rcon:
            list_resp = rcon.command("minecraft:list")
            if any(k in list_resp.lower() for k in ("unknown", "未知的", "错误", "unrecognized")):
                list_resp = rcon.command("list")
            list_out = strip_ansi(list_resp)
            list_out = re.sub(r"§[0-9a-fk-or]", "", list_out)
            try:
                tps_out = strip_ansi(rcon.command("tps"))
                tps_out = re.sub(r"§[0-9a-fk-or]", "", tps_out)
            except Exception:
                pass
            try:
                gc_out = strip_ansi(rcon.command("/gc"))
                gc_out = re.sub(r"§[0-9a-fk-or]", "", gc_out)
            except Exception:
                pass
    except Exception:
        pass
    if list_out:
        online, maxp = parse_list_response(list_out)
        if online is not None: info["online"]=online
        if maxp is not None: info["max"]=maxp
    if tps_out:
        m = re.search(r"([0-9]+\.[0-9]+)", tps_out)
        if m: info["tps"]=float(m.group(1))
    elif gc_out:
        m = re.search(r"TPS[=： ](\d+(?:\.\d+)?)", gc_out, re.IGNORECASE)
        if m: info["tps"]=float(m.group(1))
    if gc_out:
        max_m = re.search(r'最大内存[： :]\s*([\d,]+)\s*MB', gc_out)
        if max_m: info["memory_max_mb"]=int(max_m.group(1).replace(',',''))
        alloc_m = re.search(r'已分配内存[： :]\s*([\d,]+)\s*MB', gc_out)
        free_m = re.search(r'空闲内存[： :]\s*([\d,]+)\s*MB', gc_out)
        if alloc_m and free_m:
            alloc = int(alloc_m.group(1).replace(',',''))
            free = int(free_m.group(1).replace(',',''))
            info["memory_used_mb"] = alloc - free
            if info["memory_max_mb"]==0: info["memory_max_mb"]=alloc
    uptime_secs = get_mc_server_uptime_secs()
    info["uptime"] = fmt_uptime(uptime_secs)
    return info


# ==================== Recovery Mode Utilities ====================
TEXT_FILE_EXTENSIONS = {'.txt','.json','.yml','.yaml','.properties','.conf','.cfg','.ini','.md','.log','.xml','.html','.htm','.js','.css','.sh','.bat'}

def is_text_file(filename):
    ext = os.path.splitext(filename)[1].lower()
    return ext in TEXT_FILE_EXTENSIONS

def safe_plugins_path(rel_path):
    """Return the absolute path under the plugins directory, or None if out of bounds"""
    if rel_path is None:
        rel_path = ''
    root_abs = os.path.abspath(PLUGINS_DIR)
    abs_path = os.path.abspath(os.path.join(root_abs, rel_path))
    if abs_path == root_abs or abs_path.startswith(root_abs + os.sep):
        return abs_path
    return None

def is_valid_image(data):
    """Validate image via file-header magic number"""
    if len(data) < 12:
        return False
    if data[:8] == b'\x89PNG\r\n\x1a\n':
        return True
    if data[:2] == b'\xff\xd8':
        return True
    if data[:6] in (b'GIF87a', b'GIF89a'):
        return True
    if data[:2] == b'BM':
        return True
    if data[:4] == b'RIFF' and data[8:12] == b'WEBP':
        return True
    return False

def do_restore_world(task_id, zip_path):
    """Background thread: restore world from backup zip"""
    task = restore_tasks.get(task_id)
    if not task:
        return
    try:
        task['status'] = 'checking'
        task['message'] = 'Checking server status...'
        if get_server_status() == 'running':
            task['status'] = 'error'
            task['message'] = 'Server is running. Stop it before restoring'
            return

        # Recursively delete the world directory
        task['status'] = 'deleting'
        task['message'] = 'Deleting old world directory...'
        world_dir = os.path.join(MC_DIR, 'world')
        if os.path.exists(world_dir):
            shutil.rmtree(world_dir)

        # Only read the world/ directory inside the zip
        task['status'] = 'extracting'
        task['message'] = 'Extracting...'
        mc_abs = os.path.abspath(MC_DIR)
        with zipfile.ZipFile(zip_path, 'r') as zf:
            world_entries = [info for info in zf.infolist() if info.filename == 'world' or info.filename.startswith('world/')]
            total_size = sum(info.file_size for info in world_entries if not info.is_dir())
            task['total'] = total_size
            task['progress'] = 0
            extracted = 0
            for info in world_entries:
                target = os.path.abspath(os.path.join(MC_DIR, info.filename))
                if not (target == mc_abs or target.startswith(mc_abs + os.sep)):
                    continue
                if info.is_dir():
                    os.makedirs(target, exist_ok=True)
                else:
                    os.makedirs(os.path.dirname(target), exist_ok=True)
                    with zf.open(info) as src, open(target, 'wb') as dst:
                        shutil.copyfileobj(src, dst)
                    extracted += info.file_size
                    task['progress'] = extracted
                    task['percent'] = round(extracted / total_size * 100, 1) if total_size else 100.0

        task['status'] = 'done'
        task['message'] = 'Restore complete'
        task['percent'] = 100.0
    except Exception as e:
        task['status'] = 'error'
        task['message'] = f'Restore failed: {e}'

