# ==================== Routes ====================
@app.route('/')
def index():
    if 'username' not in session: return redirect(url_for('login_page'))
    return render_template_string(MAIN_PAGE)

@app.route('/login')
def login_page():
    if 'username' in session: return redirect(url_for('index'))
    return render_template_string(LOGIN_PAGE)

limiter = Limiter(
    get_remote_address,
    app=app,
    default_limits=[],
    storage_uri="memory://",
)

@app.route('/api/login', methods=['POST'])
@limiter.limit("200/hour;1000/day")
def api_login():
    data = request.get_json()
    u, p = data.get('username'), data.get('password')
    if not u or not p:
        return jsonify({"success":False,"message":"Username and password cannot be empty"})
    locked, remain = is_locked(u)
    if locked:
        mins = int(remain // 60) + (1 if remain % 60 > 0 else 0)
        return jsonify({"success":False,"message":f"Too many failed attempts. Please try again in {mins} minutes"})
    user = users_db.get(u)
    if user and check_password_hash(user['password_hash'], p):
        session['username'] = u
        session['last_activity'] = datetime.now().timestamp()
        clear_fails(u)
        audit_log(u, "Login", "Login successful", True)
        return jsonify({"success":True})
    else:
        add_fail(u)
        audit_log(u, "Login", "Wrong password", False)
        locked2, remain2 = is_locked(u)
        if locked2:
            mins = int(remain2 // 60) + (1 if remain2 % 60 > 0 else 0)
            return jsonify({"success":False,"message":f"Too many failed attempts. Please try again in {mins} minutes"})
        else:
            fails = len(login_fail_counts.get(u, []))
            return jsonify({"success":False,"message":f"Wrong password, {MAX_FAIL - fails} attempts left"})

@app.errorhandler(429)
def ratelimit_handler(e):
    ip = get_remote_address()
    blocked_ips[ip] = time.time() + 3600
    return f"""
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>403 Forbidden</title></head>
<body style="background:#000;color:red;display:flex;justify-content:center;align-items:center;height:100vh;font-size:48px;">
403 Forbidden - too many requests, please try again later <br>Your IP: {ip}
</body></html>
""", 403

@app.route('/api/logout', methods=['POST'])
@csrf_required
def api_logout():
    if 'username' in session:
        audit_log(session['username'], "Logout", "Normal logout")
    session.clear()
    return jsonify({"success":True})

@app.route('/api/user_info')
@login_required
def user_info():
    u = session['username']; user = users_db[u]
    avatar = user['avatar'] if user['avatar'].startswith('/') else f"/static/avatars/{user['avatar']}"
    return jsonify({"success":True,"username":u,"role":user['role'],"avatar":avatar})

@app.route('/api/update_profile', methods=['POST'])
@login_required
@csrf_required
def update_profile():
    cur = session['username']; new_u = request.form.get('new_username'); new_p = request.form.get('new_password')
    if new_u and new_u != cur:
        if new_u in users_db: return jsonify({"success":False,"message":"Username already exists"}), 400
        users_db[new_u] = users_db.pop(cur); session['username'] = new_u; cur = new_u
    if new_p: users_db[cur]['password_hash'] = generate_password_hash(new_p)
    save_users(users_db)
    audit_log(cur, "Update profile", f"New username: {new_u}, Password: {'changed' if new_p else 'unchanged'}")
    return jsonify({"success":True,"message":"Profile updated"})

@app.route('/api/update_avatar', methods=['POST'])
@login_required
@csrf_required
def update_avatar():
    cur = session['username']
    if 'avatar' not in request.files: return jsonify({"success":False,"message":"No file"}), 400
    file = request.files['avatar']
    if file.filename == '': return jsonify({"success":False,"message":"Filename is empty"}), 400
    ext = file.filename.rsplit('.',1)[1].lower()
    if ext not in ['png','jpg','jpeg','gif']: return jsonify({"success":False,"message":"Unsupported image format"}), 400
    fname = f"{cur}_{datetime.now().strftime('%Y%m%d%H%M%S')}.{ext}"
