@app.route('/api/verify_super_password', methods=['POST'])
def api_verify_super_password():
    ip = get_remote_address()
    locked, remain = check_super_pwd_locked(ip)
    if locked:
        hours = int(remain // 3600) + (1 if remain % 3600 > 0 else 0)
        audit_log(session.get('username', 'Unknown'), "Super password verify", f"IP {ip} has been locked", False)
        return jsonify({"success": False, "message": f"Too many failures from this IP. Try again in {hours} hours"})
    p = request.get_json().get('password')
    if verify_super_password(p):
        clear_super_pwd_fails(ip)
        session['terminal_authorized'] = True
        session['recovery_authorized'] = True
        rid = os.urandom(16).hex()
        session['recovery_sid'] = rid
        with recovery_lock:
            recovery_sessions[rid] = time.time()
        audit_log(session.get('username', 'Unknown'), "Super password verify", "Success")
        return jsonify({"success": True})
    just_locked = add_super_pwd_fail(ip)
    audit_log(session.get('username', 'Unknown'), "Super password verify", f"Failed (IP: {ip})", False)
    if just_locked:
        return jsonify({"success": False, "message": "Too many failures; this IP is locked for 24 hours"})
    fails = get_super_pwd_fail_count(ip)
    remain = SUPER_PWD_MAX_FAIL - fails
    return jsonify({"success": False, "message": f"Wrong super password ({remain} attempts left)"})

