# ==================== ops.json Lock Control API ====================
OP_JSON_PATH = os.path.join(MC_DIR, "ops.json")

@app.route('/api/op_lock_status')
@login_required
def op_lock_status():
    try:
        result = subprocess.run(['lsattr', OP_JSON_PATH], capture_output=True, text=True)
        if result.returncode != 0:
            return jsonify({"error": "Unable to read file attributes"}), 500
        attrs = result.stdout.split()[0] if result.stdout else ''
        locked = 'i' in attrs
        return jsonify({"locked": locked})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/op_lock', methods=['POST'])
@login_required
@csrf_required
def op_lock():
    data = request.get_json()
    action = data.get('action')
    if action not in ['lock', 'unlock']:
        return jsonify({"success": False, "message": "Invalid operation"}), 400
    flag = '+i' if action == 'lock' else '-i'
    cmd = ['sudo', 'chattr', flag, OP_JSON_PATH]
    try:
        subprocess.run(cmd, check=True, capture_output=True)
        audit_log(session['username'], f"{action} ops.json", "Success")
        return jsonify({"success": True, "message": f"ops.json {'locked' if action=='lock' else 'unlocked'}"})
    except subprocess.CalledProcessError as e:
        error_msg = e.stderr.decode() if e.stderr else str(e)
        return jsonify({"success": False, "message": f"Operation failed: {error_msg}"}), 500

