@app.route('/static/novnc/<path:filename>')
def serve_novnc_assets(filename):
    """Serve noVNC static files from an in-memory dict (single-file integration)"""
    if filename not in NOVNC_ASSETS:
        return "Not Found", 404
    
    ext = filename.split('.')[-1].lower()
    mime = {
        'html': 'text/html; charset=utf-8',
        'js': 'application/javascript; charset=utf-8',
        'css': 'text/css; charset=utf-8',
        'png': 'image/png',
        'svg': 'image/svg+xml',
        'woff': 'font/woff',
        'woff2': 'font/woff2',
        'ttf': 'font/ttf'
    }.get(ext, 'application/octet-stream')
    
    data = base64.b64decode(NOVNC_ASSETS[filename])
    return Response(data, mimetype=mime)

