@app.route('/vnc-proxy', websocket=True)
def vnc_proxy():
    """Flask WebSocket proxy: forward front-end WebSocket to local websockify (127.0.0.1:6080)"""
    try:
        frontend = Server.accept(request.environ)
    except Exception as e:
        return f"WebSocket accept failed: {e}", 400

    try:
        backend = ws_client.create_connection('ws://127.0.0.1:6080', timeout=5)
    except Exception as e:
        frontend.close()
        return f"Backend connect failed: {e}", 502

    stop_event = threading.Event()

    def f2b():
        try:
            while not stop_event.is_set():
                # A timeout returning None only means no data right now; never treat it as a disconnect
                data = frontend.receive(timeout=1)
                if data is None:
                    continue
                if isinstance(data, str): data = data.encode()
                backend.send(data, opcode=ws_client.ABNF.OPCODE_BINARY)
        except Exception: pass
        finally: stop_event.set()

    def b2f():
        try:
            while not stop_event.is_set():
                try:
                    # The backend is blocking; with no data it just waits and never kills itself
                    data = backend.recv()
                except Exception:
                    break
                if not data: break
                if isinstance(data, str): data = data.encode()
                frontend.send(data)
        except Exception: pass
        finally: stop_event.set()

    t1 = threading.Thread(target=f2b, daemon=True)
    t2 = threading.Thread(target=b2f, daemon=True)
    t1.start(); t2.start()
    t1.join(); t2.join()

    try: frontend.close()
    except: pass
    try: backend.close()
    except: pass
    return ''

