# ---------- Recovery Mode: Backup List ----------
@app.route('/api/recovery/backups')
def api_recovery_backups():
    if not recovery_authorized():
        return jsonify({'error': 'not found'}), 404
    items = []
    try:
        for f in glob.glob(os.path.join(BACKUP_ROOT, '*')):
            if not os.path.isfile(f):
                continue
            name = os.path.basename(f)
            lname = name.lower()
            if not (lname.startswith('backup') and lname.endswith('.zip')):
                continue
            stat = os.stat(f)
            items.append({
                'name': name,
                'size': stat.st_size,
                'size_human': sizeof_fmt(stat.st_size),
                'mtime': stat.st_mtime
            })
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})
    items.sort(key=lambda x: x['mtime'], reverse=True)
    return jsonify({'success': True, 'items': items})

