    threading.Thread(target=do_restore_world, args=(task_id, zip_path), daemon=True).start()
    audit_log(session.get('username', 'Unknown'), "Recovery restore", f"backup: {fname}")
    return jsonify({'success': True, 'task_id': task_id})

