@app.route('/api/recovery/plugins/list', methods=['POST'])
@csrf_required
def api_recovery_plugins_list():
    if not recovery_authorized():
        return jsonify({'error': 'not found'}), 404
    data = request.get_json() or {}
    rel = data.get('path', '')
    path = safe_plugins_path(rel)
    if not path or not os.path.isdir(path):
        return jsonify({'success': False, 'message': 'Invalid path'})
    items = []
    try:
        for name in os.listdir(path):
            full = os.path.join(path, name)
            try:
                stat = os.stat(full)
                items.append({
                    'name': name,
                    'is_dir': os.path.isdir(full),
                    'size': stat.st_size,
                    'mtime': stat.st_mtime
                })
            except:
                pass
    except Exception as e:
        return jsonify({'success': False, 'message': str(e)})
    items.sort(key=lambda x: (not x['is_dir'], x['name'].lower()))
    return jsonify({'success': True, 'items': items, 'path': rel})

